  "The part the brand itself fits, in its service box. Same colors, brightness, touch and battery life as new. Our longest warranty.": "وہ پارٹ جو برانڈ خود لگاتا ہے، سروس باکس میں۔ نئے جیسے رنگ، چمک، ٹچ اور بیٹری لائف۔ ہماری سب سے لمبی وارنٹی۔",
