  "This site keeps a few things in your browser so it works: your language, your cart, stars and recent searches, whether you have seen Samsoom’s tour, and your sign-in session. We do not use advertising cookies.": "یہ سائٹ کام کرنے کے لیے آپ کے براؤزر میں کچھ چیزیں رکھتی ہے: آپ کی زبان، کارٹ، اسٹارز اور حالیہ تلاشیں، کیا آپ نے سمسوم کا ٹور دیکھا، اور آپ کا سائن اِن سیشن۔ ہم اشتہاری کوکیز استعمال نہیں کرتے۔",
