  "We ship parts every week to repair shops and traders across the Middle East, Africa, Europe and Asia: door to door with our partners, or with your own shipper.": "ہم ہر ہفتے مشرقِ وسطیٰ، افریقہ، یورپ اور ایشیا کی ریپئر دکانوں اور تاجروں کو پارٹس بھیجتے ہیں: ہمارے پارٹنرز یا آپ کے اپنے شپر کے ساتھ، دروازے سے دروازے۔",
  "We ship to 28+ countries every week, door to door, and we can hand your order to your own shipper.": "ہم ہر ہفتے 28+ ممالک میں دروازے سے دروازے بھیجتے ہیں، اور آپ کا آرڈر آپ کے اپنے شپر کو دے سکتے ہیں۔",
  "We started in 2003 as Syria Tell. In 2020 the shop took the name Sam Electronics, with the same management and the same people behind the counter.": "ہم نے 2003 میں 'سیریا ٹیل' کے نام سے آغاز کیا۔ 2020 میں دکان کا نام سیم الیکٹرانکس ہوا، وہی مینجمنٹ اور کاؤنٹر کے پیچھے وہی لوگ۔",
