  'Everything on this website and in its systems (photos, designs, texts, prices and data) belongs to Sam Electronics and is protected by the copyright laws of the United Arab Emirates, including Federal Decree-Law No. 38 of 2021. A screenshot for your own reference is fine; copying, sharing or publishing it without our written permission is not.': 'اس ویب سائٹ اور اس کے سسٹمز کی ہر چیز (تصاویر، ڈیزائن، تحریریں، قیمتیں اور ڈیٹا) سام الیکٹرانکس کی ملکیت ہے اور امارات کے کاپی رائٹ قوانین، بشمول وفاقی فرمان قانون نمبر 38 برائے 2021، کے تحت محفوظ ہے۔ اپنے حوالے کے لیے اسکرین شاٹ ٹھیک ہے؛ ہماری تحریری اجازت کے بغیر نقل، شیئر یا شائع کرنا نہیں۔',
