  'I’m the shop’s own assistant, built by Sam Electronics. A real person is one tap away if you need one.': 'میں دکان کا اپنا اسسٹنٹ ہوں، جسے سام الیکٹرانکس نے بنایا۔ ضرورت ہو تو اصلی انسان ایک ٹچ دور ہے۔',
