  'I read your photo: it is a': 'میں نے آپ کی تصویر پڑھی: یہ ہے',
  'I can see an IMEI number on the photo. Send it to the team on WhatsApp and they will find the exact model.': 'تصویر میں IMEI نمبر نظر آ رہا ہے۔ اسے WhatsApp پر ٹیم کو بھیجیں، وہ درست ماڈل ڈھونڈ لیں گے۔',
  'I looked closely but couldn’t read a model on this photo. A screenshot of Settings → About phone works best, or just tell me the model.': 'میں نے غور سے دیکھا مگر اس تصویر میں ماڈل نہیں پڑھ سکا۔ سیٹنگز ← اباؤٹ فون کا اسکرین شاٹ بہترین ہے، یا بس ماڈل بتا دیں۔',
  'I can read text on photos, but I couldn’t find a model on this one. Try the label on the box, or type the model, and I’ll take it from there.': 'میں تصاویر پر لکھا پڑھ سکتا ہوں، مگر اس میں ماڈل نہیں ملا۔ ڈبے کا لیبل آزمائیں یا ماڈل لکھ دیں، باقی میں دیکھ لوں گا۔',
  'Send me a photo with the camera button: a screenshot of Settings → About phone, or the label on the box, works best. I’ll read the model for you.': 'کیمرہ بٹن سے تصویر بھیجیں: سیٹنگز ← اباؤٹ فون کا اسکرین شاٹ یا ڈبے کا لیبل بہترین ہے۔ میں ماڈل پڑھ لوں گا۔',
  'Settings → About phone → Model.': 'سیٹنگز ← اباؤٹ فون ← ماڈل۔',
  'Settings → About phone → All specs → Model.': 'سیٹنگز ← اباؤٹ فون ← تمام تفصیلات ← ماڈل۔',
  'Dial *#06# for the IMEI and send it to us: we find the exact model.': 'IMEI کے لیے ‎*#06#‎ ڈائل کریں اور ہمیں بھیجیں: ہم درست ماڈل ڈھونڈ لیں گے۔',
  'Still about your': 'ابھی بھی آپ کے',
  'Tell me the part: screen, battery, camera or charging port.': 'پرزہ بتائیں: اسکرین، بیٹری، کیمرہ یا چارجنگ پورٹ۔',
  'Sure, for which model?': 'ضرور، کس ماڈل کے لیے؟',
  'Tell me the model and I’ll find it.': 'ماڈل بتائیں، میں ڈھونڈ لوں گا۔',
  'Which one are you after?': 'آپ کو کون سا چاہیے؟',
  'good news, we have these': 'خوشخبری، یہ ہمارے پاس ہیں',
  'this is on our shelf': 'یہ ہماری شیلف پر ہے',
  'Tap + to add one to your cart.': 'کارٹ میں ڈالنے کے لیے + دبائیں۔',
  'Want it fitted? Ask me for the repair price.': 'فٹنگ چاہیے؟ مرمت کی قیمت پوچھیں۔',
  'We’re in Al Murar, Deira, Dubai.': 'ہم المرر، دیرہ، دبئی میں ہیں۔',
  'Tap below for the map and directions.': 'نقشے اور راستے کے لیے نیچے دبائیں۔',
  'Call the shop, message us on WhatsApp or WeChat, or e-mail us. We’re @samelectronics.uae on Instagram, TikTok and Facebook.': 'دکان پر کال کریں، WhatsApp یا WeChat پر میسج کریں، یا ای میل کریں۔ ہم انسٹاگرام، ٹک ٹاک اور فیس بک پر ‎@samelectronics.uae‎ ہیں۔',
  'Every part has a warranty that depends on the grade:': 'ہر پرزے کی وارنٹی ہے جو گریڈ پر منحصر ہے:',
  'Tell me the model and the part, like “A54 battery” or “iPhone 13 screen”, and I’ll show the price of each grade.': 'ماڈل اور پرزہ بتائیں، جیسے «A54 بیٹری» یا «iPhone 13 اسکرین»، میں ہر گریڈ کی قیمت دکھاؤں گا۔',
  'The dirham is pegged to the dollar, so this rate stays the same.': 'درہم ڈالر سے منسلک ہے، اس لیے یہ ریٹ ایک جیسا رہتا ہے۔',
  'That makes': 'یہ بنتا ہے',
  'The answer is': 'جواب ہے',
