  'month': 'مہینہ',
  'Copy': 'کاپی',
  'CONNECTION': 'کنکشن',
  'Open pages keep showing.': 'کھلے صفحات دکھتے رہیں گے۔',
  'Pictures may load slower.': 'تصاویر دیر سے لوڈ ہو سکتی ہیں۔',
  'Our Deira store in Dubai is open now. Allo Madrid opens soon, and I can let you know the day it does.': 'دبئی میں ہمارا دیرہ اسٹور ابھی کھلا ہے۔ Allo Madrid جلد کھلے گا، اور جس دن کھلے گا میں آپ کو بتا دوں گا۔',
  'Brand, model, part: every grade in seconds.': 'برانڈ، ماڈل، پارٹ: ہر گریڈ چند سیکنڈ میں۔',
  'Shop, repairs, trade prices and contact.': 'شاپ، مرمت، ٹریڈ قیمتیں اور رابطہ۔',
  'Change the language, sounds and currency here.': 'زبان، آوازیں اور کرنسی یہاں بدلیں۔',
  'Orders, repairs and offers land here.': 'آرڈرز، مرمت اور آفرز یہاں آتے ہیں۔',
  'Live hours, in Dubai time.': 'لائیو اوقات، دبئی کے وقت میں۔',
  'Add parts; we confirm on WhatsApp.': 'پارٹس شامل کریں؛ ہم واٹس ایپ پر تصدیق کریں گے۔',
  'Every page, in one menu.': 'ہر صفحہ، ایک مینو میں۔',
  'Tap the ? on any page.': 'کسی بھی صفحے پر ? دبائیں۔',
  'Ask me anything, any time.': 'مجھ سے کچھ بھی، کبھی بھی پوچھیں۔',
  'Soft clicks and chimes on buttons and notifications.': 'بٹنوں اور اطلاعات پر ہلکی کلک اور گھنٹیاں۔',
  'He babbles softly while he talks and during page tours.': 'وہ بات کرتے وقت اور صفحہ ٹور کے دوران دھیرے سے بڑبڑاتا ہے۔',
  'Voice style': 'آواز کا انداز',
  'Open My Bench': 'میری بینچ کھولیں',
  'Cute': 'پیارا',
  'Deeper': 'گہری',
