  'Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates. Contact: samelectronics.uae@gmail.com.': 'Sam Electronics L.L.C, Al Murar, Deira, Dubai, United Arab Emirates. رابطہ: samelectronics.uae@gmail.com.',
  'Prices, stock, delivery times and offers depend on where you are. Please do not hide your location (for example with a VPN) when you browse or order; if you do, what you see may not apply to you and we may ask you to confirm your location before we confirm an order.': 'قیمتیں، اسٹاک، ڈیلیوری کا وقت اور آفرز آپ کے مقام پر منحصر ہیں۔ براؤز یا آرڈر کرتے وقت اپنا مقام نہ چھپائیں (مثلاً VPN سے)؛ ورنہ جو آپ دیکھیں وہ شاید آپ پر لاگو نہ ہو، اور ہم آرڈر کی تصدیق سے پہلے آپ سے مقام کی تصدیق کا کہہ سکتے ہیں۔',
  'Everything on this website and in our systems (photos, designs, texts, prices and data) belongs to Sam Electronics and is protected by UAE copyright law (Federal Decree-Law No. 38 of 2021). You may keep a copy for your own reference; copying, sharing or publishing it needs our written permission.': 'اس ویب سائٹ اور ہمارے سسٹمز کی ہر چیز (تصاویر، ڈیزائن، تحریریں، قیمتیں اور ڈیٹا) Sam Electronics کی ملکیت ہے اور یو اے ای کے کاپی رائٹ قانون (وفاقی فرمانِ قانون نمبر 38، 2021) کے تحت محفوظ ہے۔ آپ اپنے حوالے کے لیے ایک نقل رکھ سکتے ہیں؛ نقل کرنے، شیئر کرنے یا شائع کرنے کے لیے ہماری تحریری اجازت درکار ہے۔',
  'Battery (essential, always on): your cart, language, sign-in and these choices. Kept until you clear them; sign-in until you sign out.': 'بیٹری (ضروری، ہمیشہ آن): آپ کی کارٹ، زبان، سائن اِن اور یہ انتخاب۔ جب تک آپ صاف نہ کریں محفوظ؛ سائن اِن سائن آؤٹ تک۔',
  'Memory Chip (preferences): currency, sounds, recent searches, starred parts and your devices. Kept 12 months.': 'میموری چپ (ترجیحات): کرنسی، آوازیں، حالیہ تلاشیں، ستارہ لگے پارٹس اور آپ کی ڈیوائسز۔ 12 ماہ محفوظ۔',
  'Diagnostics (anonymous statistics): which pages are opened and how fast they load, never your name or contact. Kept 13 months.': 'تشخیص (گمنام اعداد و شمار): کون سے صفحات کھلتے ہیں اور کتنی تیزی سے لوڈ ہوتے ہیں، کبھی آپ کا نام یا رابطہ نہیں۔ 13 ماہ محفوظ۔',
  'Antenna (marketing and offers): the kinds of parts you look at, to show matching offers. Kept 6 months.': 'اینٹینا (مارکیٹنگ اور آفرز): آپ جن اقسام کے پارٹس دیکھتے ہیں، تاکہ متعلقہ آفرز دکھائی جائیں۔ 6 ماہ محفوظ۔',
  'The banner asks once, after the welcome. Change your choice any time with "Cookie settings" at the bottom of every page, or clear everything in your browser: the site will simply forget your cart and preferences on that device. Each choice is saved with its date.': 'بینر خوش آمدید کے بعد صرف ایک بار پوچھتا ہے۔ ہر صفحے کے نیچے "کوکی سیٹنگز" سے کبھی بھی اپنا انتخاب بدلیں، یا براؤزر میں سب کچھ صاف کریں: سائٹ اس ڈیوائس پر آپ کی کارٹ اور ترجیحات بھول جائے گی۔ ہر انتخاب تاریخ کے ساتھ محفوظ ہوتا ہے۔',
  'Brand names, model names and logos (such as Apple, Samsung, Xiaomi, Huawei and others) belong to their owners. We use them only to show which phones a part fits. Sam Electronics is an independent parts seller and repair shop, and is not affiliated with, authorised by or endorsed by these brands unless a page says so.': 'برانڈ نام، ماڈل نام اور لوگو (جیسے Apple، Samsung، Xiaomi، Huawei وغیرہ) اپنے مالکان کے ہیں۔ ہم انہیں صرف یہ دکھانے کے لیے استعمال کرتے ہیں کہ کوئی پارٹ کن فونز میں فٹ ہوتا ہے۔ Sam Electronics ایک آزاد پارٹس فروش اور مرمت کی دکان ہے، اور ان برانڈز سے وابستہ، مجاز یا توثیق شدہ نہیں، جب تک کوئی صفحہ ایسا نہ کہے۔',
  'Every part is labelled with its quality and its maker. "Original" and "Service Pack" mean parts made for the brand; every other quality is a compatible part from the maker named on the label.': 'ہر پارٹ پر اس کا معیار اور بنانے والا درج ہے۔ "Original" اور "Service Pack" کا مطلب برانڈ کے لیے بنے پارٹس ہیں؛ باقی ہر معیار لیبل پر درج بنانے والے کا مطابقت رکھنے والا پارٹ ہے۔',
