  'Parts, repairs, trade, shipping and payments. Search, or pick a topic. Still stuck? Samsoom is one tap away.': 'پارٹس، مرمت، ٹریڈ، شپنگ اور ادائیگی۔ تلاش کریں یا موضوع چنیں۔ اب بھی الجھن؟ سمسوم ایک ٹیپ دور ہے۔',
