  'When your internet connection says you are in a different place than your device’s clock, you are most likely using a VPN or a proxy.': 'جب آپ کا انٹرنیٹ کنکشن آپ کی ڈیوائس کی گھڑی سے مختلف جگہ بتائے، تو غالباً آپ VPN یا پراکسی استعمال کر رہے ہیں۔',
  'Prices, stock, delivery times and offers on this website depend on where you really are. With a hidden location, what you see may not apply to you, and we may ask you to confirm your location before we confirm an order.': 'اس ویب سائٹ پر قیمتیں، اسٹاک، ڈیلیوری اوقات اور آفرز آپ کے اصل مقام پر منحصر ہیں۔ چھپے مقام کے ساتھ جو آپ دیکھیں شاید آپ پر لاگو نہ ہو، اور ہم آرڈر کی تصدیق سے پہلے مقام کی تصدیق کا کہہ سکتے ہیں۔',
  'Our terms of use ask visitors not to hide their location when browsing or ordering. If you are simply travelling, choose “I am travelling” and carry on: nothing else changes.': 'ہماری استعمال کی شرائط زائرین سے کہتی ہیں کہ براؤز یا آرڈر کرتے وقت مقام نہ چھپائیں۔ اگر آپ صرف سفر میں ہیں تو "میں سفر میں ہوں" چنیں اور جاری رکھیں: اور کچھ نہیں بدلتا۔',
  'We only compare two time zones. We never store your IP address.': 'ہم صرف دو ٹائم زونز کا موازنہ کرتے ہیں۔ ہم کبھی آپ کا IP ایڈریس محفوظ نہیں کرتے۔',
  'Browsers can only see the screenshot keys on computers (Print Screen, ⌘⇧3/4/5, Win+Shift+S). When we see one, this notice appears once and the team is told which page it was.': 'براؤزرز صرف کمپیوٹرز پر اسکرین شاٹ کیز دیکھ سکتے ہیں (Print Screen، ⌘⇧3/4/5، Win+Shift+S)۔ جب ہم ایک دیکھیں، یہ نوٹس ایک بار ظاہر ہوتا ہے اور ٹیم کو بتایا جاتا ہے کہ کون سا صفحہ تھا۔',
  'If you took it for another reason, you can safely ignore the notice. For permission, write to us from the Contact page.': 'اگر آپ نے کسی اور وجہ سے لیا ہے تو آپ نوٹس کو نظر انداز کر سکتے ہیں۔ اجازت کے لیے رابطہ صفحے سے ہمیں لکھیں۔',
