  'The dark tag with a light shows who made the part: Service Pack (the maker\'s own service box), OEM, Repaired OLED (an original OLED panel restored and tested), GX, ZY, YK and Taiwan (trusted aftermarket factories), or Other.': 'روشنی والا گہرا ٹیگ بتاتا ہے کس نے بنایا: Service Pack (بنانے والے کا سروس باکس)، OEM، Repaired OLED (اصل OLED پینل، مرمت اور ٹیسٹ شدہ)، GX، ZY، YK اور تائیوان (قابل اعتماد آفٹر مارکیٹ فیکٹریاں)، یا دیگر۔',
  'How do I pay?': 'میں ادائیگی کیسے کروں؟',
  'Cash or card at the counter, bank transfer, or a payment link on WhatsApp. The Payments page has the details.': 'کاؤنٹر پر نقد یا کارڈ، بینک ٹرانسفر، یا واٹس ایپ پر پیمنٹ لنک۔ تفصیل ادائیگی کے صفحے پر۔',
  'Can I collect it, or do you deliver?': 'خود لے جاؤں یا آپ پہنچاتے ہیں؟',
  'Collect it at the counter in Al Murar, Deira (often the same day), have it delivered in the UAE, or shipped worldwide every week.': 'المرر، دیرہ کاؤنٹر سے لیں (اکثر اسی دن)، امارات میں ڈلیوری، یا ہر ہفتے دنیا بھر میں ترسیل۔',
  'Can I return a part?': 'کیا میں پرزہ واپس کر سکتا ہوں؟',
  'A faulty part is replaced or refunded within its warranty when it is returned unfitted and undamaged, with the invoice. Fitted parts are checked on our bench first.': 'خراب پرزہ وارنٹی میں بدل دیا جاتا ہے یا رقم واپس، اگر بغیر لگائے، صحیح سالم اور انوائس کے ساتھ آئے۔ لگے ہوئے پرزے پہلے ہمارے بینچ پر چیک ہوتے ہیں۔',
  'Can I be told when a part is back or cheaper?': 'کیا پرزہ واپس آنے یا سستا ہونے پر بتایا جا سکتا ہے؟',
  'Yes. Tap the bell on any part, or use Stock alert and Price watch in Samsoom. The bell at the top rings when it happens.': 'ہاں۔ کسی بھی پرزے پر گھنٹی دبائیں، یا سمسوم میں اسٹاک الرٹ اور قیمت پر نظر استعمال کریں۔ اوپر کی گھنٹی بجے گی۔',
  'How does Compare work?': 'موازنہ کیسے کام کرتا ہے؟',
  'Tap the two-cards button on up to three parts, then Compare now: price, warranty, rating and stock side by side, with the best value marked.': 'تین پرزوں تک دو کارڈ والا بٹن دبائیں، پھر ابھی موازنہ کریں: قیمت، وارنٹی، ریٹنگ اور اسٹاک ساتھ ساتھ، بہترین نشان کے ساتھ۔',
  'Is the stock number exact?': 'کیا اسٹاک نمبر بالکل درست ہے؟',
  'It is an estimate that updates through the day. The team confirms it on WhatsApp before you pay.': 'یہ اندازہ ہے جو دن بھر اپ ڈیٹ ہوتا ہے۔ ادائیگی سے پہلے ٹیم واٹس ایپ پر تصدیق کرتی ہے۔',
  'Add parts to the cart and send the order, or tap Order on WhatsApp or WeChat on any part. The team confirms stock and the final price before you pay.': 'پرزے کارٹ میں ڈال کر آرڈر بھیجیں، یا کسی پرزے پر واٹس ایپ یا وی چیٹ پر آرڈر دبائیں۔ ادائیگی سے پہلے ٹیم اسٹاک اور حتمی قیمت کی تصدیق کرتی ہے۔',
  'Each grade has its own warranty, shown on the part. Original grades carry the longest. The full terms are on the Warranty page.': 'ہر معیار کی اپنی وارنٹی ہے جو پرزے پر لکھی ہے۔ اوریجنل کی سب سے لمبی۔ مکمل شرائط وارنٹی صفحے پر۔',
  'Apply for a trade account. Once it is approved, every part shows your trade price, and you can paste a whole parts list into Samsoom\'s Trade list.': 'ٹریڈ اکاؤنٹ کے لیے درخواست دیں۔ منظوری کے بعد ہر پرزہ آپ کی ٹریڈ قیمت دکھائے گا، اور آپ پوری فہرست سمسوم کی ٹریڈ لسٹ میں پیسٹ کر سکتے ہیں۔',
  'Every part is tested on a bench before it leaves the counter.': 'ہر پرزہ کاؤنٹر سے جانے سے پہلے بینچ پر ٹیسٹ ہوتا ہے۔',
  'Each grade carries its own warranty, written on the invoice.': 'ہر معیار کی اپنی وارنٹی ہے، انوائس پر لکھی۔',
  'Fair retail prices, and trade prices for repair shops.': 'منصفانہ ریٹیل قیمتیں، اور ریپیئر شاپس کے لیے ٹریڈ قیمتیں۔',
  'Made by a third party to fit and work like the original. A sensible middle ground.': 'تیسرے فریق کی بنی، اصل کی طرح فٹ اور کام کرتی ہے۔ معقول درمیانی راستہ۔',
  'Everyday quality at a fair price, tested on our bench before it ships.': 'روزمرہ معیار منصفانہ قیمت پر، بھیجنے سے پہلے ہمارے بینچ پر ٹیسٹ۔',
  'A good copy, one step under AAA. The budget choice for older phones.': 'اچھی کاپی، AAA سے ایک درجہ نیچے۔ پرانے فونز کے لیے سستا انتخاب۔',
  'A full-size OLED panel: deep blacks and the original look, edge to edge.': 'پورے سائز کا OLED پینل: گہرا کالا اور اصل جیسا، کنارے سے کنارے تک۔',
  'A compact OLED panel with original colours, at a lower price than OLED Big.': 'اصل رنگوں والا کمپیکٹ OLED پینل، OLED Big سے سستا۔',
  'Other qualities we can source on request. Ask the team on WhatsApp.': 'دیگر معیار درخواست پر منگوا سکتے ہیں۔ واٹس ایپ پر ٹیم سے پوچھیں۔',
  'Good news: it is in stock right now. I will still tell you if it runs out and comes back.': 'اچھی خبر: ابھی اسٹاک میں ہے۔ ختم ہو کر واپس آیا تو پھر بھی بتاؤں گا۔',
  'Done. I will ring the bell the moment it is back in stock.': 'ہو گیا۔ واپس آتے ہی گھنٹی بجاؤں گا۔',
  'Done. I will ring the bell when the price drops below': 'ہو گیا۔ قیمت اس سے کم ہوئی تو گھنٹی بجاؤں گا:',
  'Where': 'کہاں',
  'the bell at the top, and My Bench → Alerts': 'اوپر کی گھنٹی، اور My Bench ← الرٹس',
