  'The team will confirm on WhatsApp. Bring the phone with some battery so we can test it.': 'ٹیم واٹس ایپ پر تصدیق کرے گی۔ فون کچھ چارج کے ساتھ لائیں تاکہ ٹیسٹ کر سکیں۔',
  'Your trade list is with the team': 'آپ کی ٹریڈ لسٹ ٹیم کے پاس ہے',
  'Lines matched': 'میچ ہونے والی لائنیں',
  'Your Sam Grid trade prices are applied when the team confirms it.': 'ٹیم کی تصدیق پر آپ کی Sam Grid ٹریڈ قیمتیں لاگو ہوں گی۔',
  'I could not find that model. Pick it from the list, or send a photo of Settings → About.': 'یہ ماڈل نہیں ملا۔ فہرست سے چنیں، یا سیٹنگز ← بارے میں کی تصویر بھیجیں۔',
  'No orders on your account yet. Type the order number from your receipt.': 'اکاؤنٹ میں ابھی آرڈر نہیں۔ رسید سے آرڈر نمبر لکھیں۔',
  'Sign in to see your orders, or type the order number from your receipt.': 'آرڈر دیکھنے کے لیے سائن ان کریں، یا رسید سے نمبر لکھیں۔',
  'I can not see order': 'مجھے آرڈر نظر نہیں آ رہا',
  'on this account, so I passed it to the team. They will reply with its status shortly.': 'اس اکاؤنٹ میں، اس لیے ٹیم کو بھیج دیا۔ وہ جلد حالت بتائیں گے۔',
  'Add the phone, the problem, a time, your name and your number.': 'فون، مسئلہ، وقت، نام اور نمبر لکھیں۔',
  'Anything we should know? (optional)': 'کوئی بات جو ہمیں جاننی چاہیے؟ (اختیاری)',
  'Ooh, good one!': 'واہ، اچھا سوال!',
