  'Build a price list, then send or add it to the cart': 'قیمت کی فہرست بنائیں، پھر بھیجیں یا کارٹ میں ڈالیں',
  'A real person, right on the website': 'ایک اصل انسان، ویب سائٹ پر ہی',
  'Fastest for stock, prices and orders': 'اسٹاک، قیمت اور آرڈر کے لیے سب سے تیز',
  'Add our number and send a message': 'ہمارا نمبر شامل کریں اور پیغام بھیجیں',
