  'No question matches. Ask Samsoom instead.': 'کوئی سوال نہیں ملا۔ سمسوم سے پوچھیں۔',
  'File a complaint: every case gets a number and goes to the management team.': 'شکایت درج کریں: ہر کیس کو نمبر ملتا ہے اور انتظامیہ تک جاتا ہے۔',
  'Out of stock · request it': 'اسٹاک ختم · منگوائیں',
  'left (estimate)': 'باقی (اندازاً)',
  'Requested': 'منگوایا',
  'Which screen grade?': 'اسکرین کا کون سا معیار؟',
  'Ask us for this grade': 'یہ معیار ہم سے منگوائیں',
  'Type your model, e.g. A54': 'اپنا ماڈل لکھیں، مثلاً A54',
  'No model matches. Ask Samsoom and we will check.': 'کوئی ماڈل نہیں ملا۔ سمسوم سے پوچھیں، ہم چیک کریں گے۔',
  'Phone or WhatsApp': 'فون یا واٹس ایپ',
  'Repair shops and traders paste a whole parts list and get it priced and checked against stock in one go, with trade prices.': 'ریپیئر شاپس اور تاجر پوری فہرست پیسٹ کرتے ہیں اور ایک ساتھ قیمت اور اسٹاک ٹریڈ قیمت پر پاتے ہیں۔',
  'Add your phone under My devices and the shop marks every part that fits. Not sure of your model? Use Find My Part, ask Samsoom, or send him a photo of Settings → About.': 'میرے آلات میں اپنا فون شامل کریں، دکان ہر فٹ ہونے والا پرزہ نشان زد کرے گی۔ ماڈل معلوم نہیں؟ Find My Part استعمال کریں، سمسوم سے پوچھیں، یا سیٹنگز ← بارے میں کی تصویر بھیجیں۔',
  'Tip: send the team a photo of the label on the old part and they will match it for you.': 'مشورہ: پرانے پرزے کے لیبل کی تصویر ٹیم کو بھیجیں، وہ ملا دیں گے۔',
  'Tip: bring the phone with the battery above 20% so the team can test it straight away.': 'مشورہ: فون 20% سے زیادہ چارج کے ساتھ لائیں تاکہ فوراً ٹیسٹ ہو۔',
  'Tip: trade accounts see trade prices on every part once approved.': 'مشورہ: منظوری کے بعد ٹریڈ اکاؤنٹس ہر پرزے پر ٹریڈ قیمت دیکھتے ہیں۔',
  'Settings → General → About → Model Number. Tap it once to see the A-number (e.g. A2633). Or read it on the SIM tray slot.': 'سیٹنگز ← جنرل ← اباؤٹ ← ماڈل نمبر۔ ایک بار دبائیں تو A نمبر دکھے گا (مثلاً A2633)۔ یا سم ٹرے کی جگہ پر پڑھیں۔',
  'Settings → About phone → Model number (SM-A546B…). Also on the box label.': 'سیٹنگز ← فون کے بارے میں ← ماڈل نمبر (SM-A546B…)۔ ڈبے کے لیبل پر بھی۔',
  'Settings → About phone → Model (e.g. GD1YQ).': 'سیٹنگز ← فون کے بارے میں ← ماڈل (مثلاً GD1YQ)۔',
  'Shop here': 'یہاں خریدیں',
  'Shopping here': 'یہاں سے خرید رہے ہیں',
  'Pick up today · ready in 20 minutes': 'آج لیں · 20 منٹ میں تیار',
  'See all notifications': 'تمام اطلاعات دیکھیں',
  'not matched': 'نہیں ملا',
  'Removed from': 'سے ہٹا دیا',
  'Added to': 'میں شامل کیا',
  'FRAMES': 'فریم',
  'Screens, batteries, flex cables and every small part, for every popular model. Tested, graded and ready at the counter in Deira, or shipped to your door.': 'اسکرینیں، بیٹریاں، فلیکس کیبلز اور ہر چھوٹا پرزہ، ہر مقبول ماڈل کے لیے۔ ٹیسٹ شدہ، درجہ بند اور دیرہ کاؤنٹر پر تیار، یا آپ کے دروازے تک۔',
  'Original is the part the phone maker fits. Compatible is made by a third party to fit and work like it. Standard is everyday quality at a fair price. AAA is a high-grade copy close to the original, and AA a step under it. OLED Soft, OLED Big and OLED Small are OLED screens (flexible, full-size or compact panels). Incell is an LCD with the touch built in, the budget choice. Other means a quality we source on request. Every part shows its grade as a coloured tag.': 'Original وہ پرزہ ہے جو فون بنانے والا لگاتا ہے۔ Compatible تیسرا فریق بناتا ہے جو ویسے ہی فٹ اور کام کرتا ہے۔ Standard منصفانہ قیمت پر روزمرہ معیار ہے۔ AAA اصل کے قریب اعلیٰ کاپی ہے، اور AA اس سے ایک درجہ نیچے۔ OLED Soft، OLED Big اور OLED Small OLED اسکرینیں ہیں (لچکدار، پورے سائز یا کمپیکٹ پینل)۔ Incell بلٹ ان ٹچ والی LCD ہے، سستا انتخاب۔ Other وہ معیار ہے جو درخواست پر منگواتے ہیں۔ ہر پرزہ اپنا معیار رنگین ٹیگ سے دکھاتا ہے۔',
  'New medal': 'نیا تمغہ',
  'I will show you the useful tools here. It takes 20 seconds.': 'میں آپ کو یہاں کے کام کے ٹولز دکھاتا ہوں۔ 20 سیکنڈ لگیں گے۔',
  'The message': 'پیغام',
  'Add your own message (optional)': 'اپنا پیغام شامل کریں (اختیاری)',
  'e.g. This is the screen we need for the shop': 'مثلاً: یہ وہ اسکرین ہے جو دکان کو چاہیے',
